begin;
create table public.office_bank_accounts(id uuid primary key default gen_random_uuid(),brokerage_id uuid not null references public.brokerages(id),name text not null,kind text not null check(kind in ('Trust','Operating')),opening_balance numeric(15,2) not null default 0,opening_date date not null default current_date,active boolean not null default true);
create table public.office_periods(id uuid primary key default gen_random_uuid(),brokerage_id uuid not null references public.brokerages(id),period_end date not null,locked boolean not null default false,unique(brokerage_id,period_end));
create table public.office_ledger(id uuid primary key default gen_random_uuid(),brokerage_id uuid not null references public.brokerages(id),account_id uuid not null references public.office_bank_accounts(id),deal_id uuid references public.deal_files(id),entry_date date not null,description text not null check(length(trim(description))>0),amount numeric(15,2) not null check(amount<>0),reference text not null default '',reverses_id uuid unique references public.office_ledger(id),created_at timestamptz not null default now());
create table public.office_bank_lines(id uuid primary key default gen_random_uuid(),brokerage_id uuid not null references public.brokerages(id),account_id uuid not null references public.office_bank_accounts(id),entry_date date not null,description text not null,amount numeric(15,2) not null,fingerprint text not null,unique(account_id,fingerprint));
create table public.office_bank_matches(id uuid primary key default gen_random_uuid(),brokerage_id uuid not null references public.brokerages(id),bank_line_id uuid unique not null references public.office_bank_lines(id),ledger_id uuid unique not null references public.office_ledger(id));
create table public.office_reconciliations(id uuid primary key default gen_random_uuid(),brokerage_id uuid not null references public.brokerages(id),account_id uuid not null references public.office_bank_accounts(id),period_end date not null,statement_balance numeric(15,2) not null,ledger_balance numeric(15,2) not null,trust_file_total numeric(15,2),signed_by uuid not null references auth.users(id),signed_at timestamptz not null default now(),unique(account_id,period_end));
create table public.agent_payouts(id uuid primary key default gen_random_uuid(),brokerage_id uuid not null references public.brokerages(id),profile_id uuid not null references public.office_agents(id),deal_id uuid not null unique references public.deal_files(id),gross numeric(15,2) not null,gst numeric(15,2) not null,deductions numeric(15,2) not null,net numeric(15,2) not null check(net>=0),snapshot jsonb not null,status text not null default 'Authorized' check(status in ('Authorized','Paid')),authorized_by uuid not null references auth.users(id),paid_date date,payment_reference text,ledger_id uuid unique references public.office_ledger(id),created_at timestamptz not null default now());
alter table public.agent_monthly_bills add constraint monthly_bill_payout_fk foreign key(payout_id) references public.agent_payouts(id);
do $$ declare t text;begin foreach t in array array['office_bank_accounts','office_periods','office_ledger','office_bank_lines','office_bank_matches','office_reconciliations','agent_payouts'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy admin_read on public.%I for select to authenticated using(public.is_brokerage_admin(brokerage_id))',t);execute format('grant select on public.%I to authenticated',t);end loop;end $$;
create policy agent_payout_read on public.agent_payouts for select to authenticated using(exists(select 1 from public.office_agents p where p.id=profile_id and p.user_id=auth.uid()));
-- Only accounts and imported bank lines are directly insertable. Posting/sign-off uses RPCs.
create function public.guard_new_bank_account() returns trigger language plpgsql set search_path='' as $$ begin if exists(select 1 from public.office_periods where brokerage_id=new.brokerage_id and locked and period_end>=new.opening_date) then raise exception 'Account opening date is in a locked period';end if;if new.kind='Trust' and new.opening_balance<>0 then raise exception 'Allocate opening trust balances to individual file ledgers';end if;return new;end $$;
create trigger bank_account_period before insert on public.office_bank_accounts for each row execute function public.guard_new_bank_account();
create policy bank_account_add on public.office_bank_accounts for insert to authenticated with check(public.is_brokerage_admin(brokerage_id));
create function public.guard_bank_import() returns trigger language plpgsql set search_path='' as $$ begin if exists(select 1 from public.office_reconciliations where account_id=new.account_id and period_end>=new.entry_date) then raise exception 'Reconciled period is frozen';end if;if exists(select 1 from public.office_periods where brokerage_id=new.brokerage_id and locked and period_end>=new.entry_date) then raise exception 'Period is locked';end if;return new;end $$;
create trigger bank_import_period before insert on public.office_bank_lines for each row execute function public.guard_bank_import();
create policy bank_line_add on public.office_bank_lines for insert to authenticated with check(public.is_brokerage_admin(brokerage_id) and exists(select 1 from public.office_bank_accounts a where a.id=account_id and a.brokerage_id=office_bank_lines.brokerage_id));
grant insert on public.office_bank_accounts,public.office_bank_lines to authenticated;
create function public.post_office_entry(account uuid,deal uuid,entry_day date,memo text,value numeric,payment_ref text,reversal uuid default null) returns uuid language plpgsql security definer set search_path='' as $$ declare a public.office_bank_accounts;rid uuid;old public.office_ledger;bal numeric;begin
 select * into a from public.office_bank_accounts where id=account for update;if not found or not public.is_brokerage_admin(a.brokerage_id) then raise exception 'Admin access required';end if;
 if exists(select 1 from public.office_reconciliations where account_id=account and period_end>=entry_day) then raise exception 'Reconciled period is frozen; post corrections in an open period';end if;
 if entry_day<a.opening_date then raise exception 'Entry predates account opening';end if;
 if exists(select 1 from public.office_periods where brokerage_id=a.brokerage_id and locked and period_end>=entry_day) then raise exception 'Accounting period is locked';end if;
 if deal is not null and not exists(select 1 from public.deal_files where id=deal and brokerage_id=a.brokerage_id) then raise exception 'Transaction belongs to another brokerage';end if;
 if a.kind='Trust' and deal is null then raise exception 'Trust entries require a transaction';end if;
 if reversal is not null then select * into old from public.office_ledger where id=reversal;if not found or old.account_id<>account or old.deal_id is distinct from deal or value<>-old.amount then raise exception 'Reversal must exactly offset original entry';end if;end if;
 if a.kind='Trust' then select coalesce(sum(amount),0)+value into bal from public.office_ledger where account_id=account and deal_id=deal;if bal<0 then raise exception 'Trust release exceeds funds recorded for this transaction';end if;end if;
 insert into public.office_ledger(brokerage_id,account_id,deal_id,entry_date,description,amount,reference,reverses_id) values(a.brokerage_id,account,deal,entry_day,memo,round(value,2),payment_ref,reversal) returning id into rid;return rid;end $$;
create function public.match_office_bank(bank_line uuid,ledger_entry uuid) returns void language plpgsql security definer set search_path='' as $$ declare b public.office_bank_lines;l public.office_ledger;begin
 select * into b from public.office_bank_lines where id=bank_line for update;select * into l from public.office_ledger where id=ledger_entry for update;if b.id is null or l.id is null or not public.is_brokerage_admin(b.brokerage_id) or b.account_id<>l.account_id or b.brokerage_id<>l.brokerage_id or b.amount<>l.amount then raise exception 'Match requires same account, brokerage and amount';end if;
 if exists(select 1 from public.office_periods where brokerage_id=b.brokerage_id and locked and period_end>=least(b.entry_date,l.entry_date)) then raise exception 'Period is locked';end if;
 insert into public.office_bank_matches(brokerage_id,bank_line_id,ledger_id) values(b.brokerage_id,b.id,l.id);end $$;
create function public.sign_off_reconciliation(account uuid,period_day date,statement_total numeric) returns void language plpgsql security definer set search_path='' as $$ declare a public.office_bank_accounts;bal numeric;files numeric;begin
 select * into a from public.office_bank_accounts where id=account for update;if not found or not public.is_brokerage_admin(a.brokerage_id) then raise exception 'Admin access required';end if;
 if period_day<a.opening_date then raise exception 'Statement predates account opening';end if;
 if period_day<(now() at time zone 'America/Vancouver')::date-3660 or period_day>(now() at time zone 'America/Vancouver')::date then raise exception 'Invalid reconciliation date';end if;
 if exists(select 1 from public.office_ledger l where l.account_id=account and l.entry_date<=period_day and not exists(select 1 from public.office_bank_matches m join public.office_bank_lines b on b.id=m.bank_line_id where m.ledger_id=l.id and b.entry_date<=period_day)) or exists(select 1 from public.office_bank_lines b where b.account_id=account and b.entry_date<=period_day and not exists(select 1 from public.office_bank_matches m join public.office_ledger l on l.id=m.ledger_id where m.bank_line_id=b.id and l.entry_date<=period_day)) then raise exception 'Resolve unmatched entries before signing off';end if;
 select a.opening_balance+coalesce(sum(amount),0) into bal from public.office_ledger where account_id=account and entry_date<=period_day;
 if round(statement_total,2)<>bal then raise exception 'Statement balance does not equal ledger balance';end if;
 if a.kind='Trust' then select coalesce(sum(amount),0) into files from public.office_ledger where account_id=account and entry_date<=period_day;if files<>bal then raise exception 'Trust opening balance must be allocated to file ledgers before three-way reconciliation';end if;end if;
 insert into public.office_reconciliations(brokerage_id,account_id,period_end,statement_balance,ledger_balance,trust_file_total,signed_by) values(a.brokerage_id,account,period_day,statement_total,bal,files,auth.uid());end $$;
create function public.lock_office_period(period_day date) returns void language plpgsql security definer set search_path='' as $$ declare b uuid:=public.current_brokerage();begin
 if not public.is_brokerage_admin(b) then raise exception 'Admin access required';end if;
 perform 1 from public.office_bank_accounts where brokerage_id=b and active and opening_date<=period_day for update;
 if not exists(select 1 from public.office_bank_accounts where brokerage_id=b and active and opening_date<=period_day) or exists(select 1 from public.office_bank_accounts a where a.brokerage_id=b and a.active and a.opening_date<=period_day and not exists(select 1 from public.office_reconciliations r where r.account_id=a.id and r.period_end=period_day)) then raise exception 'Reconcile every active bank account at this date before locking';end if;
 insert into public.office_periods(brokerage_id,period_end,locked) values(b,period_day,true) on conflict(brokerage_id,period_end) do update set locked=true;end $$;
create function public.apply_agent_split(deal uuid) returns void language plpgsql security definer set search_path='' as $$ declare d public.deal_files;p public.office_agents;base numeric;agent numeric;begin
 select * into d from public.deal_files where id=deal for update;if not found or not public.is_brokerage_admin(d.brokerage_id) or d.review_status not in ('Submitted','Approved') or d.kind<>'Sale' then raise exception 'Submitted sale and brokerage admin required';end if;
 if exists(select 1 from public.agent_payouts where deal_id=deal) then raise exception 'Payout already authorized';end if;
 select * into p from public.office_agents where user_id=d.user_id and brokerage_id=d.brokerage_id;if not found then raise exception 'Agent profile not linked';end if;
 base=case when d.representation='listing' then d.listing_commission else d.selling_commission end;agent=round(base*p.agent_split/100,2);
 insert into public.agent_commission_allocations(deal_id,commission_before_gst,commission_gst,notes) values(deal,agent,round(agent*p.commission_gst_rate/100,2),'Agent share '||p.agent_split||'% of '||base||' before GST; brokerage retains remaining share.') on conflict(deal_id) do update set commission_before_gst=excluded.commission_before_gst,commission_gst=excluded.commission_gst,notes=excluded.notes;end $$;
create function public.authorize_agent_payout(deal uuid,through_month date) returns uuid language plpgsql security definer set search_path='' as $$ declare d public.deal_files;p public.office_agents;a public.agent_commission_allocations;ded numeric;fees numeric;rid uuid;bill public.agent_monthly_bills;begin
 select * into d from public.deal_files where id=deal for update;if not found or not public.is_brokerage_admin(d.brokerage_id) or d.kind<>'Sale' or d.review_status<>'Approved' or d.completion_date is null or d.completion_date>(now() at time zone 'America/Vancouver')::date then raise exception 'Completed, approved sale required';end if;
 select * into p from public.office_agents where user_id=d.user_id and brokerage_id=d.brokerage_id for update;if not found then raise exception 'Agent profile required';end if;
 select * into a from public.agent_commission_allocations where deal_id=deal;if not found then raise exception 'Apply and confirm agent split first';end if;
 perform public.accrue_agent_fees_through(p.id,through_month);
 select coalesce(sum(amount+gst),0) into ded from public.agent_deal_charges where deal_id=deal;
 perform 1 from public.agent_monthly_bills where profile_id=p.id and billing_month<=date_trunc('month',through_month)::date and status='Outstanding' and collection_method='Cheque deduction' for update;
 select coalesce(sum(amount+gst),0) into fees from public.agent_monthly_bills where profile_id=p.id and billing_month<=date_trunc('month',through_month)::date and status='Outstanding' and collection_method='Cheque deduction';
 if a.commission_before_gst+a.commission_gst<ded+fees then raise exception 'Fees exceed payout; resolve the shortfall before authorizing';end if;
 insert into public.agent_payouts(brokerage_id,profile_id,deal_id,gross,gst,deductions,net,snapshot,authorized_by) values(d.brokerage_id,p.id,deal,a.commission_before_gst,a.commission_gst,ded+fees,a.commission_before_gst+a.commission_gst-ded-fees,jsonb_build_object('allocation',to_jsonb(a),'plan',to_jsonb(p),'charges',(select coalesce(jsonb_agg(c),'[]'::jsonb) from public.agent_deal_charges c where c.deal_id=deal),'monthly_bills',(select coalesce(jsonb_agg(b),'[]'::jsonb) from public.agent_monthly_bills b where b.profile_id=p.id and b.billing_month<=date_trunc('month',through_month)::date and b.status='Outstanding' and b.collection_method='Cheque deduction')),auth.uid()) returning id into rid;
 for bill in select * from public.agent_monthly_bills where profile_id=p.id and billing_month<=date_trunc('month',through_month)::date and status='Outstanding' and collection_method='Cheque deduction' loop
 insert into public.agent_deal_charges(deal_id,category,description,amount,gst) values(deal,'Office fee',bill.category||' — '||bill.billing_month,bill.amount,bill.gst);
 update public.agent_monthly_bills set status='Cheque deducted',payout_id=rid where id=bill.id;end loop;
 return rid;end $$;
create function public.mark_agent_payout_paid(payout uuid,account uuid,payment_day date,cheque_ref text) returns void language plpgsql security definer set search_path='' as $$ declare p public.agent_payouts;a public.office_bank_accounts;entry uuid;begin
 select * into p from public.agent_payouts where id=payout for update;select * into a from public.office_bank_accounts where id=account;if p.id is null or not public.is_brokerage_admin(p.brokerage_id) or a.id is null or a.brokerage_id<>p.brokerage_id or a.kind<>'Operating' or p.status<>'Authorized' or length(trim(cheque_ref))=0 then raise exception 'Authorized payout, operating account and payment reference required';end if;
 if p.net>0 then entry=public.post_office_entry(account,p.deal_id,payment_day,'Agent payout',-p.net,cheque_ref);end if;
 update public.agent_payouts set status='Paid',paid_date=payment_day,payment_reference=cheque_ref,ledger_id=entry where id=payout;end $$;
-- Freeze allocation/charges once the payout is authorized; corrections require a later adjustment workflow.
create function public.guard_payout_financials() returns trigger language plpgsql security definer set search_path='' as $$ begin if exists(select 1 from public.agent_payouts where deal_id=new.deal_id) and coalesce(current_setting('realvolt.authorizing',true),'')<>'yes' then raise exception 'Payout is authorized; financial entries are locked';end if;return new;end $$;
-- Authorization itself adds the monthly charge rows before reserving them; allow only its owner-context operation.
create or replace function public.guard_payout_financials() returns trigger language plpgsql set search_path='' as $$ begin if exists(select 1 from public.deal_files d join public.office_periods p on p.brokerage_id=d.brokerage_id and p.locked and p.period_end>=d.completion_date where d.id=new.deal_id) then raise exception 'Financial period is locked';end if; if current_user in ('authenticated','anon') and exists(select 1 from public.agent_payouts where deal_id=new.deal_id) then raise exception 'Payout is authorized; financial entries are locked';end if;return new;end $$;
create trigger lock_paid_allocation before insert or update on public.agent_commission_allocations for each row execute function public.guard_payout_financials();
create trigger lock_paid_charge before insert or update on public.agent_deal_charges for each row execute function public.guard_payout_financials();
do $$ declare t text;f text;begin foreach t in array array['office_bank_accounts','office_ledger','office_bank_lines','office_bank_matches','office_reconciliations','office_periods','agent_payouts'] loop execute format('create trigger audit_record after insert or update on public.%I for each row execute function public.audit_office_change()',t);end loop;foreach f in array array['post_office_entry(uuid,uuid,date,text,numeric,text,uuid)','match_office_bank(uuid,uuid)','sign_off_reconciliation(uuid,date,numeric)','lock_office_period(date)','apply_agent_split(uuid)','authorize_agent_payout(uuid,date)','mark_agent_payout_paid(uuid,uuid,date,text)'] loop execute 'revoke all on function public.'||f||' from public,anon';execute 'grant execute on function public.'||f||' to authenticated';end loop;end $$;
commit;
